export function stableDistinctBy(rows,key){
  if(!Array.isArray(rows)||typeof key!=='string')throw Error('input');
  const seen=new Set(),out=[];
  for(const row of rows){if(!row||typeof row!=='object'||Array.isArray(row)||!Object.hasOwn(row,key))throw Error('row');const x=row[key];if(x!==null&&!['string','number','boolean'].includes(typeof x))throw Error('key');const id=JSON.stringify([typeof x,x]);if(!seen.has(id)){seen.add(id);out.push(structuredClone(row));}}
  return out;
}

export function weightedShares(total,weights){
