  const products=w.map(x=>x*BigInt(total)),out=products.map(x=>Number(x/sum));let left=total-out.reduce((a,b)=>a+b,0);
  const order=products.map((x,i)=>({i,r:x%sum})).sort((a,b)=>a.r===b.r?a.i-b.i:a.r>b.r?-1:1);for(let i=0;i<left;i++)out[order[i].i]++;return out;
}

export function reconcilePatch(record,changes){
