  const a=parse(left),b=parse(right);for(let i=0;i<3;i++)if(a.core[i]!==b.core[i])return a.core[i]<b.core[i]?-1:1;if(!a.pre||!b.pre)return a.pre?-1:b.pre?1:0;
  for(let i=0;i<Math.max(a.pre.length,b.pre.length);i++){const x=a.pre[i],y=b.pre[i];if(x===undefined)return -1;if(y===undefined)return 1;if(x===y)continue;const nx=/^\d+$/.test(x),ny=/^\d+$/.test(y);if(nx&&ny)return BigInt(x)<BigInt(y)?-1:1;if(nx!==ny)return nx?-1:1;return x<y?-1:1;}return 0;
